'use strict';
(()=>{
 const $=id=>document.getElementById(id),root=$('ruleEditor');let editing=null,expected='',pending=null;
 const text=(p,tag,value)=>{const n=document.createElement(tag);n.textContent=value;p.append(n);return n;};
 const field=(p,label,id,kind='input',values=[])=>{const l=text(p,'label',label),n=document.createElement(kind);n.id=id;if(kind==='select')for(const v of values){const o=text(n,'option',v);o.value=v;}l.append(n);return n;};
 const toolbar=text(root,'div','');toolbar.className='actions';text(toolbar,'h2','사이트에서 기준 편집');const add=text(toolbar,'button','새 기준 추가');add.type='button';
 const form=text(root,'form','');form.id='ruleEditForm';form.hidden=true;const fields=text(form,'div','');fields.className='rule-edit-fields';
 const id=field(fields,'기준 ID','ruleId');id.required=true;id.maxLength=160;
 const scope=field(fields,'적용 범위','ruleScope','select',['공통',...TagRules.WEAPONS]);
 const grade=field(fields,'평가 태그','ruleGrade','select',TagRules.GRADES);
 const priority=field(fields,'우선순위 · 낮을수록 먼저 적용','rulePriority');priority.type='number';priority.min=1;priority.max=1000000;priority.required=true;
 const active=field(fields,'활성 여부','ruleActive','select',['활성','비활성']);
 const skillMode=field(fields,'스킬 판정','ruleSkillMode','select',['정확','이상']);
 const skillFields=text(form,'fieldset','');text(skillFields,'legend','스킬 조건');const pairs=text(skillFields,'div','');pairs.className='rule-skill-fields';
 for(let i=1;i<=3;i++){const pair=text(pairs,'div','');const name=field(pair,'스킬 '+i,'ruleSkill'+i);name.setAttribute('list','skillSuggestions');name.maxLength=160;const level=field(pair,'레벨 '+i,'ruleLevel'+i);level.type='number';level.min=1;level.max=10;level.value=1;}
 const slots=text(form,'div','');slots.className='rule-edit-fields';const slotMode=field(slots,'슬롯 판정','ruleSlotMode','select',['정확','이상','무시']);
 const weaponSlots=field(slots,'무기 슬롯 · 예: 3/1','ruleWeaponSlots');const armorSlots=field(slots,'방어구 슬롯 · 예: 2/1','ruleArmorSlots');text(form,'p','극종결·종결은 기본 ‘정확’, 준종결 이하는 기본 ‘이상’입니다. 슬롯 없음은 빈칸으로 두세요.').className='hint';
 const description=field(form,'설명','ruleDescription','textarea');description.maxLength=1000;description.rows=2;
 const actions=text(form,'div','');actions.className='actions';const check=text(actions,'button','변경 미리보기');check.type='submit';const cancel=text(actions,'button','편집 취소');cancel.type='button';
 const preview=text(form,'p','');preview.className='rules-preview';preview.hidden=true;const apply=text(form,'button','이 기준 적용');apply.type='button';apply.className='primary';apply.hidden=true;
 const message=text(root,'p','');message.id='ruleEditorMessage';message.setAttribute('role','status');
 const defaultModes=()=>{const mode=['극종결','종결'].includes(grade.value)?'정확':'이상';skillMode.value=mode;slotMode.value=mode;};
 const slotState=()=>{weaponSlots.disabled=armorSlots.disabled=slotMode.value==='무시';if(slotMode.value==='무시')weaponSlots.value=armorSlots.value='';};
 const clear=()=>{pending=null;preview.hidden=true;apply.hidden=true;};
 function open(rule=null){editing=rule?.id||null;expected=JSON.stringify(RuleStore.get());form.reset();id.readOnly=!!rule;id.value=rule?.id||'web-'+crypto.randomUUID();scope.value=rule?.scope||'공통';grade.value=rule?.grade||'일반';priority.value=rule?.priority||((TagRules.GRADES.indexOf(grade.value)+1)*100);active.value=rule?.active===false?'비활성':'활성';defaultModes();if(rule){skillMode.value=rule.skillMode;slotMode.value=rule.slotMode;}for(let i=1;i<=3;i++){$('ruleSkill'+i).value=rule?.skills[i-1]?.name||'';$('ruleLevel'+i).value=rule?.skills[i-1]?.level||1;}weaponSlots.value=(rule?.weaponSlots||[]).join('/');armorSlots.value=(rule?.armorSlots||[]).join('/');description.value=rule?.description||'';slotState();clear();message.textContent='';form.hidden=false;id.focus({preventScroll:true});root.scrollIntoView({block:'start'});}
 function parseSlots(value){if(!value.trim())return [];const list=value.trim().split(/[\/ ,]+/).map(Number);if(list.length>3||list.some(n=>!Number.isInteger(n)||n<1||n>3))throw Error('슬롯은 1~3을 최대 3개 입력하세요. 예: 3/1');return list;}
 function candidate(rule,remove=false){const next=RuleStore.get().filter(r=>r.id!==editing);if(!remove){if(!editing&&RuleStore.get().some(r=>r.id===rule.id))throw Error('같은 기준 ID가 있습니다.');next.push(rule);}return TagRules.validateRules(next,SKILL_NAMES);}
 function prepare(next){pending=next;preview.textContent=`현재 ${RuleStore.get().length}개 → 적용 후 ${next.length}개 · 자동 평가가 바뀌는 보유 호석 ${RuleStore.impact(next)}개\n수동 태그와 메모는 유지됩니다.`;preview.hidden=false;apply.hidden=false;message.textContent='미리보기를 확인한 뒤 적용하세요.';}
 add.addEventListener('click',()=>open());cancel.addEventListener('click',()=>{form.hidden=true;clear();message.textContent='편집을 취소했습니다.';});grade.addEventListener('change',()=>{defaultModes();priority.value=(TagRules.GRADES.indexOf(grade.value)+1)*100;slotState();});slotMode.addEventListener('change',slotState);form.addEventListener('input',clear);form.addEventListener('change',clear);
 form.addEventListener('submit',event=>{event.preventDefault();try{const skills=[];for(let i=1;i<=3;i++)if($('ruleSkill'+i).value.trim())skills.push({name:$('ruleSkill'+i).value.trim(),level:Number($('ruleLevel'+i).value)});prepare(candidate({id:id.value.trim(),active:active.value==='활성',scope:scope.value,grade:grade.value,priority:Number(priority.value),skillMode:skillMode.value,skills,slotMode:slotMode.value,weaponSlots:parseSlots(weaponSlots.value),armorSlots:parseSlots(armorSlots.value),description:description.value.trim()}));}catch(e){clear();message.textContent=e.message.replace(/^태그기준!\d+행 · /,'');}});
 apply.addEventListener('click',()=>{if(!pending)return;try{if(!RuleStore.set(pending,expected))throw Error('저장하지 못했습니다. 보유 호석 페이지의 저장 상태를 확인하세요.');form.hidden=true;clear();renderList();message.textContent='기준을 적용하고 보유 호석 자동 평가를 갱신했습니다.';}catch(e){message.textContent=e.message;}});
 function renderList(){const rules=RuleStore.get(),needle=$('ruleListQuery').value.trim().toLocaleLowerCase();$('rulesCurrent').textContent=`기준 버전 ${CandidateContext.get().rulesVersion} · 현재 기준 ${rules.length}개 · 활성 ${rules.filter(r=>r.active).length}개`;$('rulesList').replaceChildren();for(const rule of rules.filter(r=>[r.id,r.scope,r.grade,r.description,...r.skills.map(s=>s.name)].join(' ').toLocaleLowerCase().includes(needle))){const row=text($('rulesList'),'li','');const info=text(row,'span',`${rule.scope} · ${rule.grade} · 순위 ${rule.priority}${rule.active?'':' · 비활성'} · ${rule.skills.map(s=>s.name+' Lv.'+s.level).join(' / ')||'스킬 조건 없음'} · 무기 ${rule.weaponSlots.join('/')||'없음'} / 방어구 ${rule.armorSlots.join('/')||'없음'}`);info.title=rule.id+(rule.description?' · '+rule.description:'');const edit=text(row,'button','수정');edit.type='button';edit.addEventListener('click',()=>open(rule));const remove=text(row,'button','삭제');remove.type='button';remove.className='danger';remove.addEventListener('click',()=>{open(rule);prepare(candidate(null,true));message.textContent='삭제 미리보기입니다. 적용하면 이 기준이 삭제됩니다.';});}if(!$('rulesList').children.length)text($('rulesList'),'li','표시할 기준이 없습니다. 새 기준을 추가하거나 검색어를 바꾸세요.');}
 $('ruleListQuery').addEventListener('input',renderList);$('rulesDialog').addEventListener('page-leave',()=>{form.hidden=true;clear();});document.addEventListener('inventory-state-changed',()=>{if(!$('rulesDialog').hidden)renderList();});window.RuleEditor={renderList,open};
})();
